-- All application data is in a non-exposed schema; never expose 'club' through Supabase Data API.
CREATE SCHEMA IF NOT EXISTS club;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS club.users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL DEFAULT 'PARTICIPANT' CHECK(role IN ('PARTICIPANT','ADMIN')), is_active boolean NOT NULL DEFAULT true, token_version int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS club.participant_profiles(user_id uuid PRIMARY KEY REFERENCES club.users(id) ON DELETE CASCADE, full_name text NOT NULL, phone text, department text, academic_year int CHECK(academic_year BETWEEN 1 AND 8), college text);
CREATE TABLE IF NOT EXISTS club.events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, slug text NOT NULL UNIQUE, description text DEFAULT '', banner text, event_date date NOT NULL, start_time time NOT NULL, end_time time NOT NULL, venue text NOT NULL, registration_fee integer NOT NULL DEFAULT 0 CHECK(registration_fee>=0), team_size integer NOT NULL DEFAULT 1 CHECK(team_size>0), max_participants integer NOT NULL CHECK(max_participants>0), registration_start timestamptz NOT NULL, registration_deadline timestamptz NOT NULL, status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','OPEN','CLOSED','CANCELLED','ARCHIVED')), created_at timestamptz DEFAULT now(), CHECK(registration_deadline>registration_start), CHECK(end_time>start_time));
CREATE TABLE IF NOT EXISTS club.registrations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), registration_code text UNIQUE, event_id uuid NOT NULL REFERENCES club.events(id), user_id uuid NOT NULL REFERENCES club.users(id), status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','CONFIRMED','CANCELLED')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(event_id,user_id), UNIQUE(id,event_id));
CREATE SEQUENCE IF NOT EXISTS club.registration_code_seq;
CREATE TABLE IF NOT EXISTS club.payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), registration_id uuid NOT NULL REFERENCES club.registrations(id), gateway_order_id text UNIQUE, gateway_payment_id text UNIQUE, amount integer NOT NULL CHECK(amount>=0), currency text NOT NULL DEFAULT 'INR', status text NOT NULL DEFAULT 'CREATED' CHECK(status IN ('CREATED','PAID','FAILED','REFUNDED')), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS club.event_leaders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES club.events(id), user_id uuid NOT NULL REFERENCES club.users(id), leader_code text NOT NULL UNIQUE, credential_hash text NOT NULL, created_at timestamptz DEFAULT now(), UNIQUE(event_id,user_id), UNIQUE(id,event_id));
CREATE SEQUENCE IF NOT EXISTS club.leader_code_seq;
CREATE TABLE IF NOT EXISTS club.teams(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES club.events(id), leader_id uuid NOT NULL UNIQUE, name text NOT NULL, locked boolean NOT NULL DEFAULT false, created_at timestamptz DEFAULT now(), UNIQUE(id,event_id), FOREIGN KEY(leader_id,event_id) REFERENCES club.event_leaders(id,event_id));
CREATE TABLE IF NOT EXISTS club.team_members(team_id uuid NOT NULL,event_id uuid NOT NULL,registration_id uuid NOT NULL,joined_at timestamptz DEFAULT now(),PRIMARY KEY(team_id,registration_id), UNIQUE(event_id,registration_id), FOREIGN KEY(team_id,event_id) REFERENCES club.teams(id,event_id),FOREIGN KEY(registration_id,event_id) REFERENCES club.registrations(id,event_id));
CREATE TABLE IF NOT EXISTS club.faculty(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL,designation text,department text,role text,photo text,bio text,hierarchy_level int DEFAULT 0,display_order int DEFAULT 0,is_active boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS club.student_team(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,position text,department text,photo text,github text,linkedin text,hierarchy_level int DEFAULT 0,display_order int DEFAULT 0,is_active boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS club.contact_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,email text NOT NULL,subject text NOT NULL,message text NOT NULL,status text NOT NULL DEFAULT 'UNREAD' CHECK(status IN ('UNREAD','READ','REPLIED','ARCHIVED')),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS club.audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_id uuid REFERENCES club.users(id),action text NOT NULL,target_id uuid,details jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS club.webhook_events(event_id text PRIMARY KEY,created_at timestamptz DEFAULT now());
-- Defense in depth even though club schema is not exposed through PostgREST.
DO $$ DECLARE t record; BEGIN FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='club' LOOP EXECUTE format('ALTER TABLE club.%I ENABLE ROW LEVEL SECURITY',t.tablename); END LOOP; END $$;
REVOKE ALL ON SCHEMA club FROM PUBLIC, anon, authenticated;
REVOKE ALL ON ALL TABLES IN SCHEMA club FROM PUBLIC, anon, authenticated;
